Given a character array arr[] containing only lowercase English alphabets, the task is to print the maximum length of the subarray such that the first and the last element of the sub-array are same.Examples: Input: arr[] = {'g', 'e', 'e', 'k', 's'} Output: 2 Explanation: {'e', 'e'} is the maximum length sub-array satisfying the given condition.Input: arr[] = {'a', 'b', 'c', 'd', 'a'} Output: 5 Explanation: {'a', 'b', 'c', 'd', 'a'} is the required sub-array .Table of Content[Naive Approach] Using two nested loops[Efficient Approach] Using Array[Naive Approach] Using two nested loopsThe idea is to use two nested loops where the outer loop selects each character as a potential start of a subarray, and for each start position, the inner loop searches from the end to find the rightmost occurrence of the same character, keeping track of the maximum length of such subarrays found so far.
            C++

    // C++ program to find the maximum length
// of the subarray such that the first and
// the last element of the sub-array are same.
#include<iostream>
#include<vector>
using namespace std;

int maxLenSubArray(vector<char> &arr) {
    int n = arr.size();

    int res = 0;

    // Find the maximum length of 
    // each subarray.
    for (int i=0; i<n; i++) {
        int j;

        // Find the furthest index j 
        // such that arr[i]==arr[j].
        for (j=n-1; j>=i; j--) {
            if (arr[i]==arr[j]) break;
        }

        // Compare size of current subarray.
        res = max(res, j-i+1);
    }

    return res;
}

int main() {

	vector<char> arr = {'g', 'e', 'e', 'k', 's'};
    cout << maxLenSubArray(arr);
	return 0;
}


